def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return min(budget, 20.0)

    pressure_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            pressure_bids.append(float(bid))
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
            urgent_opp += 1
        if opp.get('budget', 0) >= budget:
            rich_opp += 1

    if pressure_bids:
        highest_prev = max(pressure_bids)
        avg_prev = sum(pressure_bids) / len(pressure_bids)
    else:
        highest_prev = DAILY_SALARY * 0.6
        avg_prev = DAILY_SALARY * 0.5

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 1.0
    elif hp <= 4:
        danger += 0.6
    if no_water_days >= 2:
        danger += 1.0
    elif no_water_days >= 1:
        danger += 0.45

    market_pressure = 0.35 * scarcity
    market_pressure += 0.25 if highest_prev >= 180 else 0.0
    market_pressure += 0.15 if avg_prev >= 140 else 0.0
    market_pressure += min(0.25, 0.08 * urgent_opp)

    if day >= 8:
        market_pressure += 0.1

    if danger >= 1.4:
        target = max(highest_prev + 3.0, DAILY_SALARY * 1.35)
    elif danger >= 0.8:
        target = max(avg_prev + 4.0, DAILY_SALARY * (0.95 + 0.35 * scarcity))
    else:
        if supply >= 22 and urgent_opp == 0:
            target = DAILY_SALARY * 0.22
        elif market_pressure >= 0.75:
            target = max(avg_prev * 0.92, DAILY_SALARY * 0.9)
        elif market_pressure >= 0.45:
            target = max(DAILY_SALARY * 0.58, avg_prev * 0.72)
        else:
            target = DAILY_SALARY * 0.38

    if rich_opp >= 2 and danger < 0.8:
        target *= 0.92

    if hp >= 8 and no_water_days == 0 and supply >= 21:
        target *= 0.88

    reserve = 0.0
    if day <= 7:
        reserve = DAILY_SALARY * 1.2
    elif day <= 9:
        reserve = DAILY_SALARY * 0.6

    affordable = max(0.0, budget - reserve)
    if danger >= 0.8:
        affordable = budget

    bid = min(target, affordable if affordable > 0 else budget)

    if danger >= 1.4 and bid < DAILY_SALARY * 0.95:
        bid = min(budget, DAILY_SALARY * 0.95)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    max_prev_bid = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            max_prev_bid = max(max_prev_bid, prev['bid'])
    if no_water_days > 0:
        base_bid = min(budget, DAILY_SALARY * 0.9)
        if max_prev_bid > 0:
            bid = max(base_bid, max_prev_bid + 1)
        else:
            bid = base_bid
    else:
        if hp > 3:
            base_bid = min(budget, DAILY_SALARY * 0.4)
        else:
            base_bid = min(budget, DAILY_SALARY * 0.7)
        if max_prev_bid > 0:
            bid = max(base_bid, min(budget, max_prev_bid * 0.8))
        else:
            bid = base_bid
    bid = max(0, min(budget, bid))
    return bid
